#!/usr/bin/env bash
set -euo pipefail
IMAGE='sha256:97f1889c21c32f1798bf701c4fda80408ab2b387904b01e76463d521eaf18291'; ROOT='/var/tmp/20260815-phase11-int8-backbone-node3'; TOOLS="${ROOT}/tools"; SOURCE="${ROOT}/build/candidate.onnx"; SAMPLE="${ROOT}/sample_and_logits.pt"; RUN="${ROOT}/segment25_static_build_cpu"
exec 9>/var/tmp/phase11-int8-backbone-segment25-static-build-cpu-node3.lock; flock -n 9 || exit 75
test "$(hostname)" = machine3; test -z "$(docker ps -q)"; test "$(docker image inspect "${IMAGE}" --format '{{.Id}}')" = "${IMAGE}"
test "$(stat -c %s "${SOURCE}")" = 368047490; test "$(sha256sum "${SOURCE}"|awk '{print $1}')" = edd2c3e69b64986dc6d0b78fe32230f9a9f7eb0396c2d77fdcb6bf4c59506a7a
test "$(stat -c %s "${SAMPLE}")" = 4820344; test "$(sha256sum "${SAMPLE}"|awk '{print $1}')" = 4822aa763ccb1eba7ab3609326297255dc7d4cb41b19116f0b5b936818daec62
test "$(stat -c %s "${TOOLS}/lsmod")" = 819664; test "$(sha256sum "${TOOLS}/lsmod"|awk '{print $1}')" = 9328bce5211d360b0c7acaafdc9c4b927ac3773f7a7422600470afc5478f8e12
test "$(stat -c %s "${TOOLS}/build_phase11_int8_backbone_segment25.py")" = 4583; test "$(sha256sum "${TOOLS}/build_phase11_int8_backbone_segment25.py"|awk '{print $1}')" = eb14cb2008492b6be4ab3d1e00d36297604f7f99a841afb4a4d35b0917949ce6
test "$(stat -c %s "${TOOLS}/validate_phase11_int8_backbone_segment25_cpu.py")" = 5870; test "$(sha256sum "${TOOLS}/validate_phase11_int8_backbone_segment25_cpu.py"|awk '{print $1}')" = 17f506aca0c21ddb6a5e20327f450f62c6d8a21ce9d3f2b6ccc6c7489ebf4f72
test ! -e "${RUN}"; mkdir -p "${RUN}"; docker image inspect "${IMAGE}" >"${RUN}/image_inspect.json"; { date -Ins; hostname; printf 'variant=int8_backbone_compat_25_static_batch1_onnx_segments\noperation=build_and_cpu_sequential_parity_only\n'; free -h; } >"${RUN}/host_pre.txt" 2>&1
set +e
docker run --rm --name phase11-int8-backbone-segment25-static-build-cpu-node3 --entrypoint bash --memory=24g --pids-limit=512 -e PATH=/work/tools:/usr/local/bin:/usr/local/sbin:/usr/sbin:/usr/bin:/sbin:/bin -v "${TOOLS}:/work/tools:ro" -v "${SOURCE}:/work/source.onnx:ro" -v "${SAMPLE}:/work/sample.pt:ro" -v "${RUN}:/work/run:rw" -w /work "${IMAGE}" -lc 'python3 /work/tools/build_phase11_int8_backbone_segment25.py --source /work/source.onnx --output-dir /work/run/models --report /work/run/segment_build_report.json && python3 /work/tools/validate_phase11_int8_backbone_segment25_cpu.py --source /work/source.onnx --sample /work/sample.pt --segment-report /work/run/segment_build_report.json --output /work/run/cpu_sequential_parity.json' >"${RUN}/build_and_cpu_parity.log" 2>&1
RC=$?; set -e; printf '%s\n' "${RC}" >"${RUN}/build_and_cpu_parity.exit"; { date -Ins; free -h; } >"${RUN}/host_post.txt" 2>&1; test ! -f "${RUN}/cpu_sequential_parity.json" || cat "${RUN}/cpu_sequential_parity.json"; exit "${RC}"
